#include <iostream>
#include <cstdint>

// Demonstrating unnamed padding and zero-width alignment
struct PacketHeader {
    uint32_t version : 4;  // 4 bits
    uint32_t         : 4;  // 4 bits padding (unnamed)
    uint32_t flags   : 8;  // 8 bits
    uint32_t         : 0;  // Force alignment to next storage unit boundary
    uint32_t checksum: 16; // Starts at next 32-bit unit boundary
};

int main() {
    PacketHeader pkt{};
    pkt.version = 4;
    pkt.flags = 0xAA;
    pkt.checksum = 0xF00D;

    std::cout << "Size of PacketHeader: " << sizeof(PacketHeader) << " bytes\n";
    std::cout << "Version: " << pkt.version << "\n";
    std::cout << "Flags: 0x" << std::hex << pkt.flags << "\n";
    std::cout << "Checksum: 0x" << pkt.checksum << std::dec << "\n";

    return 0;
}

#include <iostream>
#include <string_view>
#include <array>

// Legacy-compatible unscoped enum with explicit start value
enum Month : int {
    JAN = 1, FEB, MAR, APR, MAY, JUN,
    JUL, AUG, SEP, OCT, NOV, DEC
};

int main() {
    // Array of names indexed 0..12
    constexpr std::array<std::string_view, 13> monthNames = {
        "***ERROR***",
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };

    // Safe iteration using underlying integer bounds
    for (int m = JAN; m <= DEC; ++m) {
        std::cout << m << " " << monthNames[m] << "\n";
    }

    return 0;
}

#include <iostream>
#include <cstdint>

// Demonstrating anonymous struct nested in outer struct
struct SensorPacket {
    uint16_t sensorId;

    // Anonymous struct member flattening
    struct {
        int16_t temperature;
        int16_t humidity;
    };
};

// Member-by-member comparison satisfying CERT EXP04-C
bool arePacketsEqual(const SensorPacket& a, const SensorPacket& b) {
    return (a.sensorId == b.sensorId) &&
           (a.temperature == b.temperature) &&
           (a.humidity == b.humidity);
}

int main() {
    SensorPacket p1{};
    p1.sensorId = 101;
    // Direct access to nested anonymous members
    p1.temperature = 25;
    p1.humidity = 60;

    SensorPacket p2 = p1;

    std::cout << "Packet 1 ID: " << p1.sensorId << "\n";
    std::cout << "Temperature: " << p1.temperature << " C\n";
    std::cout << "Humidity: " << p1.humidity << "%\n";
    std::cout << "Packets equal: " << (arePacketsEqual(p1, p2) ? "true" : "false") << "\n";
    std::cout << "Struct size (EXP03-C): " << sizeof(SensorPacket) << " bytes\n";

    return 0;
}
